//! Every standard algorithm — each `sce:kind="algorithm"` document under
//! `stdlib/` — is checked and generated by every backend that generates
//! algorithms, whole or in part. The backends are the generator's own answer
//! ([`emitting_in_part`]), never a list written here, so a backend that joins
//! the algorithm kind is held to the whole library the day it joins.
//!
//! A rule of the standard library is written once and generated for every
//! language (docs/adr/0085, Q8 as amended on 2026-11-08). A backend that truly
//! cannot generate one names it in [`EXCEPTIONS`] with the reason; a refusal
//! that is not listed fails, and so does a listed one that is no longer
//! refused.
//!
//! # What was wrong
//!
//! `sce:std/mesh/causal_cut` counts the members it has heard from in one
//! bounded list of records and builds the stable cut in another. Byte-buffer-
//! build v1 took exactly one buffer, the returned one, so the document was
//! refused with "2 list<record:Id> buffers declared" on every backend
//! (measured on Swift, 2026-11-08), while the library promised it to all of
//! them and three Mesh cores called the function it should have generated. No
//! test generated every standard algorithm on Swift. v2 (SCE_FORGE.md §4.12)
//! takes any number of working lists beside the output.

use std::path::{Path, PathBuf};

use sce_build::forge::codegen_matrix::emitting_in_part;
use sce_build::forge::model::ForgeKind;
use sce_build::generator::Language;
use sce_build::{check_forge_files, compile_forge_file, ForgeCompileOptions};

/// A backend that cannot generate a standard algorithm: the document, by its
/// path under `stdlib/`, the backend, and why it cannot.
struct Exception {
    document: &'static str,
    language: Language,
    reason: &'static str,
}

/// Every standard algorithm a backend that generates algorithms cannot
/// generate, each with its reason. Empty: every such backend generates every
/// standard algorithm. A document a backend refuses for a construct its
/// lowering has not reached yet is added here with that construct, never left
/// to fail unnamed; `sce:std/mesh/causal_cut` on Swift is not one.
const EXCEPTIONS: &[Exception] = &[];

fn repo_root() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR"))
        .parent()
        .expect("sce-build has a parent")
        .to_path_buf()
}

/// Whether `content` is a document of the algorithm kind: its root names it.
fn is_algorithm(content: &str) -> bool {
    let document = roxmltree::Document::parse(content).expect("a standard document parses");
    document
        .root_element()
        .attribute(("http://sce.dev/ext", "kind"))
        == Some("algorithm")
}

fn walk(current: &Path, out: &mut Vec<PathBuf>) {
    let mut entries: Vec<PathBuf> = std::fs::read_dir(current)
        .expect("read the stdlib directory")
        .map(|entry| entry.expect("a directory entry").path())
        .collect();
    entries.sort();
    for path in entries {
        if path.is_dir() {
            walk(&path, out);
        } else if path.extension().is_some_and(|e| e == "scxml")
            && is_algorithm(&std::fs::read_to_string(&path).expect("read a standard document"))
        {
            out.push(path);
        }
    }
}

/// Every standard algorithm, by its path on disk, in path order.
fn standard_algorithms() -> Vec<PathBuf> {
    let mut out = Vec::new();
    walk(&repo_root().join("stdlib"), &mut out);
    out
}

/// The path of `document` under `stdlib/`, as [`EXCEPTIONS`] names it.
fn under_stdlib(document: &Path) -> String {
    document
        .strip_prefix(repo_root().join("stdlib"))
        .expect("a standard document is under stdlib/")
        .to_string_lossy()
        .replace('\\', "/")
}

fn exception_for(document: &str, language: Language) -> Option<&'static Exception> {
    EXCEPTIONS
        .iter()
        .find(|e| e.document == document && e.language == language)
}

fn options_for(language: Language) -> ForgeCompileOptions {
    let mut options = ForgeCompileOptions::default();
    // Go names every import by its module path.
    if matches!(language, Language::Go) {
        options.go_module_prefix = Some("example.com/consumer/generated".to_string());
    }
    options
}

#[test]
fn every_standard_algorithm_checks_and_generates_on_every_algorithm_backend() {
    let documents = standard_algorithms();
    assert!(
        documents
            .iter()
            .any(|d| under_stdlib(d) == "mesh/causal_cut.scxml"),
        "the causal cut is a standard algorithm: {documents:?}"
    );
    let languages: Vec<Language> = emitting_in_part(ForgeKind::Algorithm).collect();
    assert!(
        languages.len() >= 6,
        "the algorithm kind is generated by the six whole backends at least: {languages:?}"
    );
    let mut failures = Vec::new();
    for &language in &languages {
        let name = language.canonical_name();
        let options = options_for(language);
        // The check, as a consumer that regenerates the library asks it: one
        // verdict per document, in the order given.
        let checks = check_forge_files(&documents, language, &[], &options);
        for (document, check) in documents.iter().zip(&checks) {
            let rel = under_stdlib(document);
            match (check.passed(), exception_for(&rel, language)) {
                (true, None) | (false, Some(_)) => {}
                (false, None) => failures.push(format!(
                    "{name}: {rel} is refused by the check: {}",
                    check
                        .diagnostics
                        .iter()
                        .map(|d| d.message.as_str())
                        .collect::<Vec<_>>()
                        .join("; ")
                )),
                (true, Some(exception)) => failures.push(format!(
                    "{name}: {rel} is checked, but is listed as an exception ({}): drop it",
                    exception.reason
                )),
            }
        }
        // The generation, which writes the unit the check said it would.
        for document in &documents {
            let rel = under_stdlib(document);
            if exception_for(&rel, language).is_some() {
                continue;
            }
            match compile_forge_file(document, language, &[], &options) {
                Ok(output) if output.files.iter().any(|(_, text)| !text.trim().is_empty()) => {}
                Ok(_) => failures.push(format!("{name}: {rel} generated no code")),
                Err(refused) => {
                    failures.push(format!("{name}: {rel} is refused by generate: {refused}"))
                }
            }
        }
    }
    assert!(
        failures.is_empty(),
        "{} standard algorithm verdict(s) over {} document(s) and {} backend(s) are wrong:\n{}",
        failures.len(),
        documents.len(),
        languages.len(),
        failures.join("\n")
    );
}

/// An exception names a standard algorithm, a backend that generates algorithms
/// and a reason, so a stale or misspelled one cannot excuse anything; and the
/// causal cut is never one on Swift.
#[test]
fn each_exception_names_a_standard_algorithm_a_backend_and_a_reason() {
    let documents: Vec<String> = standard_algorithms()
        .iter()
        .map(|d| under_stdlib(d.as_path()))
        .collect();
    let languages: Vec<Language> = emitting_in_part(ForgeKind::Algorithm).collect();
    for exception in EXCEPTIONS {
        assert!(
            documents.iter().any(|d| d == exception.document),
            "{} is no standard algorithm",
            exception.document
        );
        assert!(
            languages.contains(&exception.language),
            "{}: {} generates no algorithm, so it needs no exception",
            exception.document,
            exception.language.canonical_name()
        );
        assert!(
            !exception.reason.trim().is_empty(),
            "{} on {}: an exception says why",
            exception.document,
            exception.language.canonical_name()
        );
    }
    assert!(
        exception_for("mesh/causal_cut.scxml", Language::Swift).is_none(),
        "the causal cut is generated on Swift, as on every backend"
    );
}
